// node tests/lvi_engine.test.js
// Parity: the JS engine must match a spreadsheet built with the classic Calc Engine formulas (tests/fixtures/lvi_golden.json,
// generated by tests/lvi_reference_workbook.py with fictional inputs) to within $0.01.
const assert = require("assert");
const eng = require("../app/site/lvi_engine.js");
global.lviRun = eng.lviRun; global.lviFx = eng.lviFx;
const S = require("../app/site/lvi_scenarios.js");
const G = require("./fixtures/lvi_golden.json");
let checks = 0;
function parity(c, results) {
  c.scenarios.forEach((s, i) => {
    const r = eng.lviRun(c.settings, c.loans, c.invs, s, c.months);
    for (const m of ["12", "60", String(c.months)]) {
      for (const k of ["nw", "loans", "inv", "cumInt"]) {
        const got = r.rows[+m][k], exp = results[i][m][k];
        assert.ok(Math.abs(got - exp) < 0.01, `${s.name} month ${m} ${k}: ${got} vs ${exp}`); checks++;
      }
    }
  });
}
parity(G.case, G.results);
parity(G.rebate_case, G.rebate_results);

// FX-aware mode: off = spreadsheet; on = foreign reducing-balance loan shrinks in USD as the currency weakens.
const c = JSON.parse(JSON.stringify(G.case)); c.loans[0].type = "Compound";
const off = eng.lviRun(c.settings, c.loans, c.invs, c.scenarios[0], 60);
const on = eng.lviRun({ ...c.settings, fxAwareForeignLoans: true }, c.loans, c.invs, c.scenarios[0], 60);
assert.ok(on.rows[60].bal[0] < off.rows[60].bal[0], "fx-aware should shrink the foreign loan's USD balance"); checks++;
const flat = eng.lviRun({ ...c.settings, fxAwareForeignLoans: true, fxDepOverride: 0 }, c.loans, c.invs, c.scenarios[0], 60);
assert.ok(Math.abs(flat.rows[60].bal[0] - off.rows[60].bal[0]) < 0.01, "with 0% drift, fx-aware equals spreadsheet mode"); checks++;

// Scenario builder: only from config; no loans -> nothing to compare.
const cfg = { loans: [{ name: "Student", kind: "student", currency: "USD", outstanding: 20000, rate: 0.06, type: "Simple-flat", min_payment: 250, current_payment: 400 }],
  investments: [{ name: "Index", expected_return: 0.15, weight: 1 }], lvi: { monthly_budget: 1200, years: 10, current_investing_monthly: 300, step_up: 0.03 } };
const g = S.lviSettings(cfg), sc = S.lviScenarios(cfg, g);
assert.deepStrictEqual(sc.map(x => x.id), ["A", "B", "C", "D"]); checks++;
assert.strictEqual(sc[0].invs[0].amt, 950); checks++;               // A: budget - minimums
assert.strictEqual(sc[1].loans[0].amt, 1200); checks++;             // B: everything to the loan
const notes = S.lviRedPen(cfg, g).map(n => n.text).join(" | ");
assert.ok(/Simple-flat/.test(notes) && /best-decade/.test(notes) && /raise every year/.test(notes) && /Compare D/.test(notes), notes); checks++;
console.log(`lvi engine: ${checks} checks passed`);
